   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="老康斯坦丁的手指突然攥紧，他别过脸，肩膀几不可察的颤了颤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她……倒是什么都告诉你了。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以我才明白她心里的挣扎，更佩服她愿意直面痛苦的勇气。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她愿意回到康斯坦丁家，要付出多大的勇气，我无法估量——", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我只希望，她能解开心结，继续以命星骑士烁曦的身份，将阳光照相维拉提亚的每一处。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="老康斯坦丁沉默了很久，才缓缓开口，像是卸下了什么重担。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我知道，你和克拉伦斯不是真正的恋人。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……！", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="星都的谣言传得再凶，我也分得清真假。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [102]={next_id=103, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但我不在乎这些谣言，我只在乎，她愿意回家了。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [103]={next_id=104, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="老康斯坦丁声音低了些，他打开酒瓶，瓶口向下，将麦酒撒在墓碑旁。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [104]={next_id=105, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="以前她不愿意回来，是因为我。她每次寄信回来，琳梅尔其实都想让我来看。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [105]={next_id=106, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但我不敢看，我怕看到她出事的消息，更怕看到她怨我的话。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [106]={next_id=107, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他苦笑着，继续倒着酒，任由酒液溅在裤子上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [107]={next_id=108, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="直到你陪她回来，我才发现，她脸上的笑容变多了，说话也愿意直视着我的眼睛了。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [108]={next_id=109, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她……变成了一个正常的女孩，而不是只会嚷嚷着荣耀和奉献的骑士。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [109]={next_id=110, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……谢谢你，链尉官。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [110]={next_id=111, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="锚点降临的灾难，我也知晓一些……我经历过星征，明白那会有多么恐怖。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [111]={next_id=112, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可我这个做父亲的，却什么都做不了。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [112]={next_id=113, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他的声音渐渐低沉起来，如同麦酒般苦涩。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [113]={next_id=114, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="星征带走了我两个孩子，之后我一听到“骑士”、“星征”就发抖……我怕她也走这条路，怕我连最后一个孩子都留不住。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [114]={next_id=115, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可现在我知道……我错了。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [115]={next_id=116, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的身体里流着康斯坦丁的血液，注定不会庸碌一生，所以反而是我在妨碍她。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [116]={next_id=117, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如果当年我真的拦住了她，会有什么样的后果……我至今也不敢去想。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [117]={next_id=118, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="只是现在……唉，那丫头和我一样的倔脾气，看着我也心里别扭。", msg_color="", msg_size=0, talker="老康斯坦丁", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7195", 0, 0, -32, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [118]={next_id=119, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="老康斯坦丁眉毛扭在一起，眼里尽是疲惫。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他和你所说的，与你来时的猜想如出一辙。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
